import{_ as a,o as n,c as e,a2 as i}from"./chunks/framework.DqYch1Cg.js";const k=JSON.parse('{"title":"Node 进程管理与优雅停机","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/20deploy/s_deploy_4-node_process.md","filePath":"概念与原理/20deploy/s_deploy_4-node_process.md","lastUpdated":1794211306000}'),p={name:"概念与原理/20deploy/s_deploy_4-node_process.md"};function l(t,s,r,o,d,h){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="node-进程管理与优雅停机" tabindex="-1">Node 进程管理与优雅停机 <a class="header-anchor" href="#node-进程管理与优雅停机" aria-label="Permalink to &quot;Node 进程管理与优雅停机&quot;">​</a></h1><h2 id="进程活着-不代表服务健康" tabindex="-1">进程活着，不代表服务健康 <a class="header-anchor" href="#进程活着-不代表服务健康" aria-label="Permalink to &quot;进程活着，不代表服务健康&quot;">​</a></h2><p>开发时的 <code>node app.js</code> 依赖当前终端。服务器需要明确进程由谁启动、异常后如何恢复、日志保留多久、发布时如何退出。健康检查还需要区分：进程是否存活（liveness）、是否可以接收业务（readiness）。短暂数据库故障不宜引发无休止的应用重启。</p><p>传统单机可选择 systemd 或 PM2；容器通常直接运行 Node，由容器平台管理重启。避免同时叠加多套进程守护，却不清楚信号由谁接收。</p><h2 id="pm2-的学习要点" tabindex="-1">PM2 的学习要点 <a class="header-anchor" href="#pm2-的学习要点" aria-label="Permalink to &quot;PM2 的学习要点&quot;">​</a></h2><p>使用 ecosystem 文件集中声明应用名、入口、工作目录、实例数和环境。ESM 项目中可使用 <code>ecosystem.config.cjs</code>：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exports</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  apps: [{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;learning-api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    cwd: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/srv/learning-api/current&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    script: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;dist/main.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    instances: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    exec_mode: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fork&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    kill_timeout: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    env: { NODE_ENV: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;production&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, PORT: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>数据库口令等通过运行环境或密钥服务注入，不提交在配置中。<code>pm2 logs</code> 和 <code>pm2 describe learning-api</code> 用于观察；开机恢复需结合当前用户的 <code>startup</code> / <code>save</code> 流程验证。更换 Node 路径后也要核对恢复脚本。</p><p>cluster / reload 可以降低切换中断，但不自动保证请求不丢失；还需要就绪协调、排空和共享状态设计。多实例中的定时任务、内存 Session 和 WebSocket 会话不能默认继续保持单进程语义。</p><h2 id="停机时数据库怎么处理" tabindex="-1">停机时数据库怎么处理？ <a class="header-anchor" href="#停机时数据库怎么处理" aria-label="Permalink to &quot;停机时数据库怎么处理？&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下线就绪状态 / 从流量入口摘除</span></span>
<span class="line"><span>  → 停止接收新工作（HTTP、队列、定时任务）</span></span>
<span class="line"><span>  → 在截止时间内等待在途请求和事务完成</span></span>
<span class="line"><span>  → 关闭应用拥有的连接池 / 数据库客户端</span></span>
<span class="line"><span>  → 完成退出；超时由上层管理器强制结束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>NestJS 需调用 <code>enableShutdownHooks()</code> 接收支持的系统信号，主动 <code>app.close()</code> 也能触发关闭钩子。结合应用生命周期安排排空与资源释放，避免仍在执行的请求因提前关闭连接池失败。各层超时要协调，管理器留给应用的时间要覆盖预期清理窗口。</p><ul><li><strong>正常下线</strong>：停止新查询，等待已开始的工作，然后调用 Prisma <code>$disconnect()</code> 或连接池对应的关闭方法；不要关闭共享 PostgreSQL 服务。</li><li><strong>网络掉线</strong>：应用未必能发送退出消息；数据库或代理会通过 TCP、超时等机制发现断开。未提交事务在会话终止后回滚，释放时间不一定立即。</li><li><strong>提交响应丢失</strong>：客户端看到超时不能证明事务未提交。写操作重试需要幂等键、唯一约束或结果查询；不要无限重试。</li><li><strong>强杀 / 宿主机断电</strong>：<code>SIGKILL</code> 不执行清理钩子；数据库服务自身依靠 WAL 等机制恢复，并不依赖应用完成清理。</li></ul><p>连接池大小要按应用副本数合计，并为迁移和运维留连接。大查询与长事务应有执行时限，关闭时仍需要验证驱动 / ORM 的具体行为。</p><p><strong>自测：</strong> 为什么不在进程退出回调里等待异步清理？应用中断后数据库是否立即知道？如何判断超时的订单创建是否已成功？</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/%E9%83%A8%E7%BD%B2%E7%9B%B8%E5%85%B3%E7%9F%A5%E8%AF%86/pm2" target="_blank" rel="noreferrer">个人 PM2 笔记</a>；<a href="https://pm2.keymetrics.io/docs/usage/signals-clean-restart/" target="_blank" rel="noreferrer">PM2 Graceful shutdown</a>；<a href="https://docs.nestjs.com/fundamentals/lifecycle-events" target="_blank" rel="noreferrer">NestJS 生命周期</a>；<a href="https://www.postgresql.org/docs/current/runtime-config-connection.html" target="_blank" rel="noreferrer">PostgreSQL 连接配置</a>。</p></blockquote>`,16)])])}const E=a(p,[["render",l]]);export{k as __pageData,E as default};
